codeExample.bad:
// Fires the delete action the instant the pointer goes down,
// with no way to cancel by dragging away before release
deleteButton.addEventListener('pointerdown', () => {
  deleteItem();
});

codeExample.good:
// Waits for the pointer to be released while still over the button
// before triggering the action, so moving away first cancels it
let pressedOverButton = false;
deleteButton.addEventListener('pointerdown', () => {
  pressedOverButton = true;
});
deleteButton.addEventListener('pointerup', (event) => {
  if (pressedOverButton && event.target === deleteButton) {
    deleteItem();
  }
  pressedOverButton = false;
});
